// فصل 03 از کتاب — تبدیل‌شده از نسخهٔ HTML؛ ویرایش دستی لازم نیست.
// Chapter 03 of the book — converted from the HTML edition; generated file.

export const n = 3;
export const num = "03";
export const title = "سه درخت — Working Tree، Index و Repository";
export const label = "فصل ۳ · سه درخت Git";
export const part = 0;
export const html = "<p class=\"lead\">Git فایل‌ها را هم‌زمان در سه جا نگه می‌دارد: آنچه در ادیتور می‌بینی، پیش‌نویس کامیت بعدی، و آخرین عکس ثبت‌شده. اگر این سه را قاطی کنی، <code>reset</code> و Save و Commit برایت یکی به نظر می‌رسند.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>سه درخت را نام ببری و نقش هر کدام را بکشی</li>\n<li>وضعیت فایل را در VS Code بخوانی: U، M، A، D</li>\n<li>تفاوت <em>unstaged</em> و <em>staged</em> را با مثال نشان دهی</li>\n<li>بگویی <code>add</code>، <code>restore</code> و <code>commit</code> دقیقاً چه چیزی را کپی می‌کنند</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">🧠 مدل ذهنی</span></span></h2>\n<p class=\"keep-next\">Git فایل‌ها را در سه لایه نگه می‌دارد:</p>\n<ol>\n<li><strong>Working Tree</strong> — فایل‌هایی که در Explorer می‌بینی و با Save ذخیره می‌کنی. هنوز تاریخچه نیست.</li>\n<li><strong>Index (Staging Area)</strong> — پیش‌نویس کامیت بعدی. <code>git add</code> یا دکمهٔ Stage فایل را از دیسک به این پیش‌نویس کپی می‌کند.</li>\n<li class=\"keep-next\"><strong>Repository (HEAD)</strong> — آخرین عکس ثبت‌شده. فقط <code>commit</code> این لایه را جلو می‌برد.</li>\n</ol>\n<div class=\"diagram\">\n<img src=\"/book/figures/three-trees.svg\" alt=\"سه درخت Git\"/>\n<p class=\"figcap\">شکل ۲ — add از Working به Index می‌رود؛ commit از Index یک شیء commit می‌سازد.</p>\n</div>\n<div class=\"callout callout-note\"><div class=\"callout-title\">فرمول طلایی</div>\n<p><strong><code>status</code> = diff(Working, Index) + diff(Index, HEAD)</strong></p>\n<p>دو ستون تغییرات در VS Code دقیقاً همین دو diff هستند.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🔍 خواندن <code>git status</code></span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">وضعیت را با چشم مسلح ببین</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>status<span style=\"color: #F8F8F2\"> </span>-sb\n<span style=\"color: #959077\"># ## main</span>\n<span style=\"color: #959077\">#  M src/auth.ts      # فاصله + M یعنی تغییر در Working، هنوز stage نشده</span>\n<span style=\"color: #959077\"># M  src/api.ts       # M در ستون اول یعنی staged</span>\n<span style=\"color: #959077\"># MM README.md        # هم staged هم بعدش دوباره ویرایش شده</span>\n<span style=\"color: #959077\"># ?? notes.txt        # untracked — Git اصلاً نمی‌شناسدش</span>\n</pre></div>\n<p class=\"keep-next\">در VS Code همین اطلاعات چنین دیده می‌شود:</p>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>نشانه</th>\n<th>معنی</th>\n<th>اقدام</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>U</strong></td>\n<td>Untracked</td>\n<td>Stage یا به <code>.gitignore</code> بسپار</td>\n</tr>\n<tr>\n<td><strong>M</strong></td>\n<td>Modified</td>\n<td>Stage / Discard</td>\n</tr>\n<tr>\n<td><strong>A</strong></td>\n<td>Added</td>\n<td>فایل جدید staged</td>\n</tr>\n<tr>\n<td><strong>D</strong></td>\n<td>Deleted</td>\n<td>حذف staged یا بازیابی</td>\n</tr>\n<tr>\n<td><strong>C</strong></td>\n<td>Conflict</td>\n<td>Resolve در ادیتور</td>\n</tr>\n</tbody>\n</table></div><h2><span class=\"hx\"><span class=\"hx-t\">🧪 آزمایش ۳۰ ثانیه‌ای</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">سه درخت را حس کن</span></div><pre><span style=\"color: #F8F8F2\">echo </span><span style=\"color: #E6DB74\">&quot;v1&quot;</span><span style=\"color: #F8F8F2\"> </span>&gt;<span style=\"color: #F8F8F2\"> </span>hello.txt\ngit<span style=\"color: #F8F8F2\"> </span>add<span style=\"color: #F8F8F2\"> </span>hello.txt<span style=\"color: #F8F8F2\">          </span><span style=\"color: #959077\"># Working = Index  (هر دو v1)  HEAD هنوز ندارد</span>\ngit<span style=\"color: #F8F8F2\"> </span>commit<span style=\"color: #F8F8F2\"> </span>-m<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;v1&quot;</span><span style=\"color: #F8F8F2\">         </span><span style=\"color: #959077\"># هر سه = v1</span>\n\n<span style=\"color: #F8F8F2\">echo </span><span style=\"color: #E6DB74\">&quot;v2&quot;</span><span style=\"color: #F8F8F2\"> </span>&gt;<span style=\"color: #F8F8F2\"> </span>hello.txt<span style=\"color: #F8F8F2\">      </span><span style=\"color: #959077\"># Working=v2  Index=v1  HEAD=v1</span>\ngit<span style=\"color: #F8F8F2\"> </span>add<span style=\"color: #F8F8F2\"> </span>hello.txt<span style=\"color: #F8F8F2\">          </span><span style=\"color: #959077\"># Working=v2  Index=v2  HEAD=v1</span>\ngit<span style=\"color: #F8F8F2\"> </span>commit<span style=\"color: #F8F8F2\"> </span>-m<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;v2&quot;</span><span style=\"color: #F8F8F2\">         </span><span style=\"color: #959077\"># هر سه = v2</span>\n</pre></div>\n<p>حالا می‌فهمی چرا «کامیت نکردم ولی Save کردم» تاریخچه را عوض نمی‌کند — Save فقط Working Tree است.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🎛️ فرمان‌ها روی کدام درخت؟</span></span></h2>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>فرمان</th>\n<th>Working</th>\n<th>Index</th>\n<th>Repo</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>ویرایش در VS Code / Save</td>\n<td>✓</td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><code>git add</code> / Stage</td>\n<td></td>\n<td>✓</td>\n<td></td>\n</tr>\n<tr>\n<td><code>git commit</code></td>\n<td></td>\n<td></td>\n<td>✓</td>\n</tr>\n<tr>\n<td><code>git restore file</code></td>\n<td>✓</td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><code>git restore --staged</code></td>\n<td></td>\n<td>✓</td>\n<td></td>\n</tr>\n<tr>\n<td><code>git reset --soft</code></td>\n<td></td>\n<td></td>\n<td>✓ (HEAD حرکت)</td>\n</tr>\n<tr>\n<td><code>git reset --mixed</code></td>\n<td></td>\n<td>✓</td>\n<td>✓</td>\n</tr>\n<tr>\n<td><code>git reset --hard</code></td>\n<td>✓</td>\n<td>✓</td>\n<td>✓</td>\n</tr>\n</tbody>\n</table></div><div class=\"callout callout-danger\"><div class=\"callout-title\">reset --hard</div>\n<p><code>--hard</code> هر سه درخت را با کامیت هدف یکی می‌کند و تغییرات ذخیره‌نشده را می‌کشد. در VS Code معادل <em>Discard All Changes</em> + حرکت HEAD است. تا فصل ۸ بدون تور ایمنی (<code>reflog</code>) نزدیکش نشو.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🖼️ در VS Code کجایند این درخت‌ها؟</span></span></h2>\n<ul>\n<li><strong>Explorer</strong> = Working Tree</li>\n<li><strong>Source Control → Changes</strong> = diff(Working, Index)</li>\n<li><strong>Source Control → Staged Changes</strong> = diff(Index, HEAD)</li>\n<li><strong>Timeline / Git Graph</strong> = Repository</li>\n</ul>\n<p class=\"keep-next\">وقتی فایلی را Stage می‌کنی، از لیست Changes به Staged می‌پرد — یعنی کپی snapshot آن فایل به Index.</p>\n<div class=\"cols\">\n<div class=\"col good\"><div class=\"col-title\">عادت Senior</div>\n<p><code>git add -p</code> یا Stage انتخابی در VS Code (روی hunk). کامیت را مثل پاراگراف می‌نویسی نه مثل سطل زباله.</p>\n</div>\n<div class=\"col bad\"><div class=\"col-title\">عادت Junior</div>\n<p><code>git add .</code> کورکورانه. فایل env، آرتیفکت بیلد و رمز داخل کامیت می‌رود.</p>\n</div>\n</div>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Junior — Staging یعنی چه؟</strong> سبد خرید قبل از پرداخت. commit پرداخت است.</p>\n<p><strong>Mid — چرا Index وجود دارد؟</strong> تا یک Working شلوغ را به چند کامیت معنادار بشکنی.</p>\n<p><strong>Senior — Index از نظر داده چیست؟</strong> یک درخت مرتب‌شده از cache entryها (مسیر، mode، OID، stat) که <code>commit</code> آن را به یک tree object تبدیل می‌کند.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li>سه درخت را بدون نگاه به کتاب نام می‌بری</li>\n<li><code>M</code> در ستون اول و دوم <code>status -sb</code> را بلدی</li>\n<li>می‌دانی Save ≠ Commit</li>\n<li>Stage انتخابی را به <code>add .</code> ترجیح می‌دهی</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> اولین مخزن واقعی — <code>init</code>، <code>add</code>، <code>commit</code>، <code>log</code>.</p></div>";
export default { n, num, title, label, part, html };
